mapper.select:
SELECT repayment_schedule_id
FROM installment_delinquency_charge
WHERE installment_delinquency_charge_id = #{installmentDelinquencyChargeId}

mapper.update:
UPDATE installment_delinquency_charge
SET paid_delinquency_charge = paid_delinquency_charge + #{amount}
WHERE installment_delinquency_charge_id = #{installmentDelinquencyChargeId}
